ALTER TABLE public.project_evidence ADD COLUMN IF NOT EXISTS file_path text NULL;
ALTER TABLE public.project_resources ADD COLUMN IF NOT EXISTS file_path text NULL;
INSERT INTO storage.buckets(id,name,public,file_size_limit,allowed_mime_types) VALUES('project-files','project-files',false,10485760,ARRAY['image/jpeg','image/png','image/webp','image/heic','text/plain','application/pdf','application/msword','application/vnd.openxmlformats-officedocument.wordprocessingml.document']) ON CONFLICT(id) DO UPDATE SET public=false,file_size_limit=10485760,allowed_mime_types=EXCLUDED.allowed_mime_types;
CREATE POLICY project_files_upload_member ON storage.objects FOR INSERT TO authenticated WITH CHECK(storage.objects.bucket_id='project-files' AND (storage.foldername(storage.objects.name))[1]=auth.uid()::text AND EXISTS(SELECT 1 FROM public.project_members pm WHERE pm.user_id=auth.uid() AND pm.project_id::text=(storage.foldername(storage.objects.name))[2]));
CREATE POLICY project_files_read_authorized ON storage.objects FOR SELECT TO authenticated USING(storage.objects.bucket_id='project-files' AND ((storage.foldername(storage.objects.name))[1]=auth.uid()::text OR EXISTS(SELECT 1 FROM public.project_evidence e JOIN public.projects p ON p.id=e.project_id WHERE e.file_path=storage.objects.name AND (public.is_admin() OR p.created_by=auth.uid() OR public.is_class_homeroom_teacher(p.class_id) OR EXISTS(SELECT 1 FROM public.project_members pm WHERE pm.project_id=p.id AND pm.user_id=auth.uid()))) OR EXISTS(SELECT 1 FROM public.project_resources r JOIN public.projects p ON p.id=r.project_id WHERE r.file_path=storage.objects.name AND (public.is_admin() OR p.created_by=auth.uid() OR public.is_class_homeroom_teacher(p.class_id) OR EXISTS(SELECT 1 FROM public.project_members pm WHERE pm.project_id=p.id AND pm.user_id=auth.uid())))));
CREATE POLICY project_files_update_owner ON storage.objects FOR UPDATE TO authenticated USING(storage.objects.bucket_id='project-files' AND (storage.foldername(storage.objects.name))[1]=auth.uid()::text) WITH CHECK(storage.objects.bucket_id='project-files' AND (storage.foldername(storage.objects.name))[1]=auth.uid()::text);
CREATE POLICY project_files_delete_owner ON storage.objects FOR DELETE TO authenticated USING(storage.objects.bucket_id='project-files' AND (storage.foldername(storage.objects.name))[1]=auth.uid()::text);